import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def read_csv_file(packet_dir, filename):
    """Read CSV file and return list of dicts."""
    filepath = os.path.join(packet_dir, filename)
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        return list(reader)

def excel_date_to_iso(excel_date_str):
    """Convert Excel serial date to ISO format YYYY-MM-DD."""
    try:
        # Excel date (days since 1899-12-30)
        days = int(float(excel_date_str))
        base = datetime(1899, 12, 30)
        date = base + timedelta(days=days)
        return date.strftime('%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def process_packet(packet_dir, manifest_json):
    # Parse manifest
    manifest = json.loads(manifest_json)
    pairs = manifest['pairs']
    facts = manifest['facts']

    # Group pairs by rule_id and entity
    entity_data = {}
    for pair in pairs:
        rule_id, entity = pair.split('::')
        if rule_id not in entity_data:
            entity_data[rule_id] = {}
        if entity not in entity_data[rule_id]:
            entity_data[rule_id][entity] = {'facts': {}}

    # Read LCA disclosure data
    lca_data = {}
    try:
        lca_records = read_csv_file(packet_dir, 'lca_disclosure.csv')
        for record in lca_records:
            case_num = record['CASE_NUMBER']
            lca_data[case_num] = record
    except FileNotFoundError:
        pass  # Handle case where file doesn't exist

    # Process each rule
    for rule_id, entities in entity_data.items():
        for entity in entities:
            record = lca_data.get(entity)

            if rule_id == 'lca.wage_105':
                # Process wage facts
                if record:
                    # Offered wage
                    offered_wage = record.get('WAGE_RATE_OF_PAY_FROM')
                    if offered_wage and offered_wage.strip():
                        entity_data[rule_id][entity]['facts']['offered wage'] = [
                            offered_wage,
                            'lca_disclosure'
                        ]
                    else:
                        entity_data[rule_id][entity]['facts']['offered wage'] = 'ABSENT'

                    # Prevailing wage
                    prevailing_wage = record.get('PREVAILING_WAGE')
                    if prevailing_wage and prevailing_wage.strip():
                        entity_data[rule_id][entity]['facts']['prevailing wage'] = [
                            prevailing_wage,
                            'lca_disclosure'
                        ]
                    else:
                        entity_data[rule_id][entity]['facts']['prevailing wage'] = 'ABSENT'
                else:
                    entity_data[rule_id][entity]['facts']['offered wage'] = 'ABSENT'
                    entity_data[rule_id][entity]['facts']['prevailing wage'] = 'ABSENT'

            elif rule_id == 'lca.three_years':
                # Process date facts
                if record:
                    # Begin date
                    begin_date = record.get('BEGIN_DATE')
                    if begin_date and begin_date.strip():
                        iso_begin = excel_date_to_iso(begin_date)
                        if iso_begin:
                            entity_data[rule_id][entity]['facts']['begin date'] = [
                                iso_begin,
                                'lca_disclosure'
                            ]
                        else:
                            entity_data[rule_id][entity]['facts']['begin date'] = 'ABSENT'
                    else:
                        entity_data[rule_id][entity]['facts']['begin date'] = 'ABSENT'

                    # End date
                    end_date = record.get('END_DATE')
                    if end_date and end_date.strip():
                        iso_end = excel_date_to_iso(end_date)
                        if iso_end:
