import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def read_csv_file(packet_dir, filename):
    """Read CSV file and return list of dicts."""
    filepath = os.path.join(packet_dir, filename)
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        return list(reader)

def excel_serial_to_date(serial):
    """Convert Excel serial number to YYYY-MM-DD string."""
    if serial == '':
        return None
    try:
        # Excel's epoch is 1899-12-30 (or 1900-01-00)
        base = datetime(1899, 12, 30)
        days = int(float(serial))
        date = base + timedelta(days=days)
        return date.strftime('%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def process_lca_disclosure(rows, entity, rule_id, facts_needed):
    """Process lca_disclosure.csv for given entity and rule."""
    result = {}
    doc_name = "lca_disclosure"

    # Find row for this entity
    matching_rows = [row for row in rows if row['CASE_NUMBER'] == entity]

    if not matching_rows:
        # Entity not found in this document
        for fact in facts_needed:
            result[fact] = "ABSENT"
        return result

    if len(matching_rows) > 1:
        # Multiple rows for same entity - check for conflicts
        return process_multiple_rows(matching_rows, rule_id, facts_needed, doc_name)

    # Single row
    row = matching_rows[0]

    if rule_id == "lca.wage_105":
        # Offered wage from WAGE_RATE_OF_PAY_FROM
        offered_wage = row.get('WAGE_RATE_OF_PAY_FROM', '').strip()
        if offered_wage == '':
            result['offered wage'] = "ABSENT"
        else:
            # Convert to decimal string
            try:
                # Remove commas if present
                offered_wage = offered_wage.replace(',', '')
                # Convert to float and back to string to normalize
                offered_wage = str(float(offered_wage))
                result['offered wage'] = [offered_wage, doc_name]
            except (ValueError, TypeError):
                result['offered wage'] = "ABSENT"

        # Prevailing wage from PREVAILING_WAGE
        prevailing_wage = row.get('PREVAILING_WAGE', '').strip()
        if prevailing_wage == '':
            result['prevailing wage'] = "ABSENT"
        else:
            try:
                prevailing_wage = prevailing_wage.replace(',', '')
                prevailing_wage = str(float(prevailing_wage))
                result['prevailing wage'] = [prevailing_wage, doc_name]
            except (ValueError, TypeError):
                result['prevailing wage'] = "ABSENT"

    elif rule_id == "lca.three_years":
        # Begin date from BEGIN_DATE
        begin_date = row.get('BEGIN_DATE', '').strip()
        if begin_date == '':
            result['begin date'] = "ABSENT"
        else:
            date_str = excel_serial_to_date(begin_date)
            if date_str:
                result['begin date'] = [date_str, doc_name]
            else:
                result['begin date'] = "ABSENT"

        # End date from END_DATE
        end_date = row.get('END_DATE', '').strip()
        if end_date == '':
            result['end date'] = "ABSENT"
        else:
            date_str = excel_serial_to_date(end_date)
            if date_str:
                result['end date'] = [date_str, doc_name]
            else:
                result['end date'] = "ABSENT"

    return result

def process_multiple_rows(rows, rule_id, facts_needed, doc_name):
    """Handle case where entity appears multiple times in same document."""
    result = {}

    if rule_id == "lca.wage_105":
        # Check for conflicts in offered wage
        offered_wages = set()
        for row in rows:
            wage = row.get('WAGE_RATE_OF_PAY_FROM', '').strip()
            if wage != '':
                try:
                    wage = wage.replace(',', '')
                    offered_wages.add(str(float(wage)))
                except (ValueError, TypeError):
                    pass

        if len(offered_wages) == 0:
            result['offered wage'] = "ABSENT"
        elif len(offered_wages) == 1:
            result['offered wage'] = [list(offered_wages)[0], doc_name]
        else:
            result['offered wage'] = "CONFLICT"

        # Check for conflicts in prevailing wage
        prevailing_wages = set()
        for row in rows:
            wage = row.get('PREVAILING_WAGE', '').strip()
            if wage != '':
                try:
                    wage = wage.replace(',', '')
                    prevailing_wages.add(str(float(wage)))
                except (ValueError, TypeError):
                    pass

        if len(prevailing_wages) == 0:
            result['prevailing wage'] = "ABSENT"
        elif len(prevailing_wages) == 1:
            result['prevailing wage'] = [list(prevailing_wages)[0], doc_name]
        else:
            result['prevailing wage'] = "CONFLICT"

    elif rule_id == "lca.three_years":
        # Check for conflicts in begin date
        begin_dates = set()
        for row in rows:
            date_val = row.get('BEGIN_DATE', '').strip()
            if date_val != '':
                date_str = excel_serial_to_date(date_val)
                if date_str:
                    begin_dates.add(date_str)

        if len(begin_dates) == 0:
            result['begin date'] = "ABSENT"
        elif len(begin_dates) == 1:
            result['begin date'] = [list(begin_dates)[0], doc_name]
        else:
            result['begin date'] = "CONFLICT"

        # Check for conflicts in end date
        end_dates = set()
        for row in rows:
            date_val = row.get('END_DATE', '').strip()
            if date_val != '':
                date_str = excel_serial_to_date(date_val)
                if date_str:
                    end_dates.add(date_str)

        if len(end_dates) == 0:
            result['end date'] = "ABSENT"
        elif len(end_dates) == 1:
            result['end date'] = [list(end_dates)[0], doc_name]
        else:
            result['end date'] = "CONFLICT"

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Read manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Read all CSV files in packet directory
    csv_files = [f for f in os.listdir(packet_dir) if f.endswith('.csv')]
    csv_data = {}

    for csv_file in csv_files:
        if csv_file == 'lca_disclosure.csv':
            csv_data['lca_disclosure'] = read_csv_file(packet_dir, csv_file)

    # Process each pair
    result = {}

    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::')
        facts_needed = manifest['facts'][rule_id]

        # Based on rules, we know which document to check
        if rule_id in ['lca.wage_105', 'lca.three_years']:
            if 'lca_disclosure' in csv_data:
                entity_result = process_lca_disclosure(
                    csv_data['lca_disclosure'], 
                    entity, 
                    rule_id, 
                    facts_needed
                )
            else:
                # Document not found
                entity_result = {fact: "ABSENT" for fact in facts_needed}
        else:
            # Unknown rule
            entity_result = {fact: "ABSENT" for fact in facts_needed}

        result[pair] = entity_result

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

